func (f *fakeDB) ListWorkspaces(ctx context.Context) ([]database2.Workspace, error) {
	if ac, ok := authmw.FromContext(ctx); ok {
		accessible := make(map[string]bool, len(ac.AccessibleWorkspaceIDs))
		for _, id := range ac.AccessibleWorkspaceIDs {
			accessible[id] = true
		}
		out := make([]database2.Workspace, 0)
		for _, w := range f.workspaces {
			if accessible[database2.UUIDString(w.ID)] {
				out = append(out, w)
			}
		}
		return out, nil
	}
	return f.workspaces, nil
}
func (f *fakeDB) GetWorkspace(ctx context.Context, workspaceID string) (database2.Workspace, error) {
	if ac, ok := authmw.FromContext(ctx); ok {
		accessible := make(map[string]bool, len(ac.AccessibleWorkspaceIDs))
		for _, id := range ac.AccessibleWorkspaceIDs {
			accessible[id] = true
		}
		if !accessible[workspaceID] {
			return database2.Workspace{}, database2.ErrNotFound
		}
	}
	for _, w := range f.workspaces {
		if database2.UUIDString(w.ID) == workspaceID {
			return w, nil
		}
	}
