// TestGetWorkspace_CrossTenantIsolation_404 proves that a user whose accessible
// workspace set contains ws-A receives HTTP 404 (not 403, not 200) when requesting ws-B.
// This exercises the full HTTP path: auth context injection → handler → fakeDB scoping.
func TestGetWorkspace_CrossTenantIsolation_404(t *testing.T) {
	const wsA = "11111111-1111-1111-1111-111111111111"
	const wsB = "55555555-5555-5555-5555-555555555555"

	// ws-B exists in the database but belongs to a different organisation.
	var wsOrgY database2.Workspace
	_ = wsOrgY.ID.Scan(wsB)
	wsOrgY.Name = "Org Y Workspace"
	wsOrgY.Slug = "org-y-workspace"
	_ = wsOrgY.UpdatedAt.Scan(time.Now())

	db := &fakeDB{workspaces: []database2.Workspace{wsOrgY}}

	// User is in org X and can only access ws-A — not ws-B.
	ac := &authmw.AuthCtx{
		UserID:                 "user-org-x",
		OrganizationID:         "org-x-id",
		AccessibleWorkspaceIDs: []string{wsA},
	}
	r := newAuthTestRouter(db, &fakeAdapter{}, ac)

	w := httptest.NewRecorder()
