// newAuthTestRouter creates a test router that injects ac into every request context,
// simulating the RequireAuth middleware for handler-level auth tests.
func newAuthTestRouter(db service.DatabaseReader, adp service.AdapterCaller, ac *authmw.AuthCtx) *gin.Engine {
	gin.SetMode(gin.TestMode)
	svc := service.New(db, adp, 30*time.Minute)
	h := handler.New(svc)
	r := gin.New()
	r.Use(func(c *gin.Context) {
		c.Request = c.Request.WithContext(authmw.SetAuthCtx(c.Request.Context(), ac))
		c.Next()
	})
	api := r.Group("/api")
	h.RegisterRoutes(api)
	return r
}

// --- tests ---

type testAPIEnvelope struct {
	Success bool            `json:"success"`
	Data    json.RawMessage `json:"data"`
	Error   *testAPIError   `json:"error"`
}

type testAPIError struct {
	Code      domain.ErrorCode `json:"code"`
	Message   string           `json:"message"`
	Retryable bool             `json:"retryable"`
	Source    string           `json:"source"`
}

func decodeAPIData[T any](t *testing.T, body []byte) T {
	t.Helper()
	var envelope testAPIEnvelope
	if err := json.Unmarshal(body, &envelope); err != nil {
		t.Fatalf("decode response envelope: %v", err)
	}
	if !envelope.Success {
		t.Fatalf("expected success envelope, got body=%s", string(body))
	}
	if envelope.Error != nil {
		t.Fatalf("did not expect error field in success envelope: %+v", envelope.Error)
	}
	var out T
	if err := json.Unmarshal(envelope.Data, &out); err != nil {
		t.Fatalf("decode response data: %v", err)
	}
	return out
}

func decodeAPIError(t *testing.T, body []byte) testAPIError {
	t.Helper()
	var envelope testAPIEnvelope
	if err := json.Unmarshal(body, &envelope); err != nil {
		t.Fatalf("decode error envelope: %v", err)
	}
	if envelope.Success {
		t.Fatalf("expected error envelope, got body=%s", string(body))
	}
	if envelope.Error == nil {
		t.Fatalf("expected error body, got body=%s", string(body))
	}
	return *envelope.Error
}

